import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    strings = []
    for _ in range(n):
        strings.append(next(iterator))

    def get_key(s):
        key = []
        for idx, char in enumerate(s):
            if (idx + 1) % 2 == 1:
                key.append(char)
            else:
                key.append(chr(ord('Z') - ord(char) + ord('A')))
        return tuple(key)

    indexed_strings = [(get_key(strings[i]), i + 1) for i in range(n)]

    indexed_strings.sort(key=lambda x: x[0])

    result = [str(item[1]) for item in indexed_strings]
    print(" ".join(result))

if __name__ == "__main__":
    solve()
